33	const DEDUP_RUN = /\bdedup\b|\bcanon now (?:covers|owns)\b/i;
34	
35	const rule = {
36	  id: 'dedup-prune-integrity',
37	  severity: 'blocking',
38	  scope: 'work',
39	  doc: 'packs/grow_with_claudinite/tasks/growth-dedup/task.md',
40	  description: 'A dedup edit only removes portable text — it never grows a local pack or re-imports a canon rule into it',
41	  why: 'the growth-dedup routine has reworded partially-covered items instead of stripping them — restating the canon rule inside the local pack, the inverse of dedup — and every dedup edit must shrink the pack, not grow it',
42	
