57	          fix: 'delegate the portable rule to the canon and keep only this project\'s residue — never restate the canon rule, its fix, or which pack owns it (use the pack\'s "(canon): here …" convention)',
58	        }));
59	      }
60	    }
61	
62	    // (2) A dedup run must shrink the pack it prunes, never grow it.
63	    if (work.commits.some((m) => DEDUP_RUN.test(m))) {
64	      for (const file of prose) {
65	        const base = work.readBase(file);
66	        const head = work.read(file);
