20	// --- fixture transcript lines -----------------------------------------------
21	
22	const ts = (m) => `2026-07-19T09:${String(m).padStart(2, '0')}:00.000Z`;
23	const userLine = (m, text) => JSON.stringify({ type: 'user', timestamp: ts(m), message: { content: text } });
24	const assistantLine = (m, text) => JSON.stringify({
25	  type: 'assistant', timestamp: ts(m), message: { content: [{ type: 'text', text }] },
26	});
27	// --- pure helpers ------------------------------------------------------------
28	
29	test('parseLines keeps raw lines paired with parsed entries and skips junk', () => {
30	  const text = `${userLine(1, 'hi')}\nnot json\n${assistantLine(2, 'yo')}\n`;
31	  const lines = parseLines(text);
32	  assert.equal(lines.length, 2);
33	  assert.equal(lines[0].raw, userLine(1, 'hi'));
34	  assert.equal(lines[0].entry.type, 'user');
35	});
36	
37	test('bundleStreams merges sidechain entries into timestamp order', () => {
38	  const main = parseLines(`${userLine(1, 'a')}\n${assistantLine(4, 'd')}`);
39	  const side = parseLines(`${assistantLine(2, 'b')}\n${assistantLine(3, 'c')}`);
40	  const bundled = bundleStreams([main, side]);
41	  assert.deepEqual(bundled.map((l) => l.entry.timestamp), [ts(1), ts(2), ts(3), ts(4)]);
42	});
43	
44	test('bundleStreams keeps a timestampless entry with its predecessor', () => {
45	  const main = parseLines(`${userLine(1, 'a')}\n${JSON.stringify({ type: 'queue-operation' })}\n${userLine(5, 'b')}`);
46	  const side = parseLines(assistantLine(3, 'mid'));
47	  const bundled = bundleStreams([main, side]);
48	  assert.equal(bundled[1].entry.type, 'queue-operation'); // stays glued to ts(1), before ts(3)
49	});
50	
51	test('sliceAfter is strict and drives delta capture (the twice-merged session)', () => {
52	  const first = bundleStreams([parseLines(`${userLine(1, 'task 1')}\n${assistantLine(2, 'done 1')}`)]);
53	  const lastCaptured = maxTimestamp(first);
54	  assert.equal(lastCaptured, ts(2));
55	  const wholeSession = bundleStreams([parseLines([
56	    userLine(1, 'task 1'), assistantLine(2, 'done 1'),
57	    userLine(3, 'task 2'), assistantLine(4, 'done 2'),
58	  ].join('\n'))]);
59	  const delta = sliceAfter(wholeSession, lastCaptured);
60	  assert.deepEqual(delta.map((l) => l.entry.timestamp), [ts(3), ts(4)]); // ts(2) itself excluded
61	  assert.deepEqual(sliceAfter(wholeSession, null).length, 4); // no prior capture → everything
62	});
63	
64	test('buildRedactionValues enumerates env fail-safe: unknown vars in, structural and short ones out', () => {
65	  const values = buildRedactionValues({
66	    MY_DB_PASSWORD: 'hunter2hunter2',
67	    UNKNOWN_INJECTED: 'mystery-value-99',
68	    PATH: '/usr/local/bin:/usr/bin',
69	    NODE_ENV: 'production',
70	    LC_ALL: 'en_US.UTF-8',
71	    SHORT: 'abc',
72	  });
73	  const names = values.map((v) => v.name);
74	  assert.ok(names.includes('MY_DB_PASSWORD'));
75	  assert.ok(names.includes('UNKNOWN_INJECTED'), 'a var the allowlist never heard of must be redacted');
76	  assert.ok(!names.includes('PATH') && !names.includes('NODE_ENV') && !names.includes('LC_ALL'));
77	  assert.ok(!names.includes('SHORT'), 'sub-minimum-length values collide with prose');
78	});
79	
80	test('buildRedactionValues carries the JSON-escaped form for values with special characters', () => {
81	  const values = buildRedactionValues({ TRICKY: 'pa"ss\\word-123' });
82	  const forms = values.filter((v) => v.name === 'TRICKY').map((v) => v.form);
83	  assert.ok(forms.includes('pa"ss\\word-123'));
84	  assert.ok(forms.includes('pa\\"ss\\\\word-123'), 'the form as it appears inside a raw JSONL line');
85	});
86	
87	test('scrub replaces enumerated values wherever they appear, longest form first', () => {
88	  const values = buildRedactionValues({ A: 'abcdefgh1234', B: 'abcdefgh1234-XYZ99' });
89	  const out = scrub('key=abcdefgh1234-XYZ99 and bare abcdefgh1234', values);
