import noEnforcementNarration from './no-enforcement-narration.mjs';
import packIndependence from './pack-independence.mjs';

// The canon home repo's own curation pack — the fleet-facing work only the
// Claudinite home runs: promoting members' lessons into the shared canon (the
// growth lifecycle's central stage) and policing the corpus's packs/ tree.
// (Prose-to-checks is no longer canon-only: it moved to grow_with_claudinite as a
// per-repo task with a `pack_paths` config — the canon runs it over its own packs/
// + local packs like any repo, per the per-project-scheduling redesign.)
//
// A LOCAL pack (.claudinite/local/packs/), by owner decision (2026-07-19): the
// canon home's curation duties are project-specific content — Claudinite
// maintaining Claudinite — so they live on the home's own capture surface, not
// in the portable packs/ canon. Its tasks are discovered structurally from this
// pack's own `tasks/<name>/task.mjs` by the repo's scheduler
// (engine/scheduler/discover.mjs), so none is declared here. Declared by hand in
// exactly one repo (this one, as "local/canon-curation"); that
// declaration cardinality is what makes its tasks central-once: a pack task
// runs per DECLARING repo, so one declaring repo means one unit per night, with
// no bespoke orchestrator step. Un-declaring it freezes canon absorption
// without touching the members' side (grow_with_claudinite).
export default {
  id: 'canon-curation',
  detect: null,
  marker: null,
  prose: null,
  // Packs-tree segregation is barriers CONFIGURATION, never code this pack
  // runs: pack-independence is contributed as manifest data and the barriers
  // pack builds it into the rule (pack-independence.mjs — pure data, the same
  // composition basics uses for claudinite-isolation).
  requires: ['barriers'],
  contributes: { barriers: [packIndependence] },
  // The prose-narration rule polices pack prose CONTENT (not segregation), so
  // it stays a code check, bundled here.
  rules: [noEnforcementNarration],
  // writing-claudinite-skills is canon-home activity (authoring corpus skills), so
  // this pack bundles it under its own skills/ — members author no corpus skills.
};

// Pack independence — as BARRIERS CONFIGURATION, not code. A pack's code
// imports only its OWN files and the engine surface; another pack's abilities
// arrive by DECLARING the dependency (`requires` on the pack manifest) and
// passing configuration, and a helper both sides need moves into checks/lib.
// A cross-pack import crashes every consumer that vendors the importer without
// its target (the vendor set ships a pack only when declared, and ships no
// canon-internal tree at all) — the failure the gated vendored-mount flip
// aborts on.
//
// This module is pure DATA: the barriers pack builds it into the rule
// (canon-curation `requires` barriers and carries this under `contributes` on
// its manifest — the same declaration-and-configuration composition the rule
// itself mandates; no code here checks anything). The `siblings` edge guards
// each pack under packs/ in turn; `to: "*"` confines it to itself plus the
// engine surface in `allow`; `scope: "imports"` keeps the ban on the coupling
// class that crashes — code imports — while prose stays free to talk about
// packs. The `allow` list IS the engine surface — the one always-vendored
// engine/ root (#385); a new surface root would join it here, loudly — the
// barrier fails closed, never silently widens. The vendor
// writer's coherence guard (vendoring/compute-vendor-set.mjs) backstops the same invariant at
// vendoring time.
//
// Home-only twice over: declared solely by the canon home (a contributed rule
// runs only where its contributor is active), and `gateDir` keeps it inert
// anywhere a packs/ tree doesn't exist.
export default {
  id: 'pack-independence',
  description: 'A pack\'s code imports only its own files and the engine surface — another pack\'s abilities arrive through declaration (requires) and configuration, never by importing its code',
  why: 'the vendor set ships a pack only when declared, so a cross-pack import crashes every consumer that vendors one pack without the other; abilities cross pack boundaries through declaration and configuration',
  doc: 'extending.md',
  crossingExcuse: 'if the crossing is deliberate, excuse it with accept: [{ "rule": "pack-independence", "path": "<file>", "reason": "..." }] in .claudinite-checks.json (a pack-shipped barrier takes no per-rule except entries)',
  gateDir: 'packs',
  edges: [{
    siblings: 'packs',
    to: '*',
    scope: 'imports',
    allow: [
      'engine',
    ],
    reason: 'a pack imports only its own files and the engine surface — declare the dependency and pass configuration (a contributed rule), or move the shared helper into engine/checks_helpers',
  }],
};

