import { sep, basename } from 'node:path';
import { fileURLToPath } from 'node:url';
import { realpathSync } from 'node:fs';
import { finding } from '../../engine/checks/helpers/findings.mjs';
import { runRule } from '../../engine/checks/helpers/work.mjs';
import { buildContext } from '../../engine/checks/helpers/repo-context.mjs';
import { LOCAL_PACKS_SUBDIR, LEGACY_LOCAL_PACKS_SUBDIR } from '../../engine/pack_loader/pack-registry.mjs';

// The write-surface gate for the repo-side growth runs (extract, dedup): the
// extract PR auto-merges with no human review, so the boundary needs a machine
// guarantee, not a prose request. A growth run announces itself with a commit
// subject starting "Claudinite growth:" (its skill pins the title); when a
// branch carries such a commit, the change must fit the surface:
//
//   - under .claudinite/local/packs/ (legacy .claudinite/local_packs/ accepted
//     during the rename window): anything — the local packs are the capture
//     surface, add/modify/delete freely;
//   - everywhere else: ONLY whole comment lines inserted into existing files —
//     the usage-site gotcha extract's method mandates ("a comment right at the
//     call site"). No rewritten or removed lines, no new files, no deletions:
//     an insertion-only comment diff cannot change behavior, which is what
//     makes it safe to land unreviewed.
//
// Sibling of canon-curation's promote-scope gate (the canon-side write
// surface). Promote can't self-gate — nothing in a diff marks it as a promote
// run, so CI keys on its branch prefix — but a growth run marks ITSELF via the
// pinned commit subject, so this rule self-gates and runs everywhere the pack
// is active: at the session Stop hook (work scope), and as a CLI on every PR
// in the canon repo's CI (via canon-curation's growth-scope-gate.mjs there).
//
// Local packs live under either root during the rename transition; git emits
// '/'-separated paths, so the platform-joined constants are normalized.
const LOCAL_ROOTS = [LOCAL_PACKS_SUBDIR, LEGACY_LOCAL_PACKS_SUBDIR]
  .map((s) => `${s.split(sep).join('/')}/`);

const GROWTH_RUN = /^Claudinite growth:/;

const inSurface = (p) => LOCAL_ROOTS.some((root) => p.startsWith(root));

// Comment syntax by file type — what an inserted line outside the local packs
// must be. Deliberately fail-closed: a file type this table doesn't know can't
// be verified, so it stays out of the unattended surface (the finding says so).
const C_LIKE = { line: ['//'], block: ['/*', '*/'] };
const HASH = { line: ['#'] };
const DASH = { line: ['--'] };
const XML = { block: ['<!--', '-->'] };
const COMMENT_SYNTAX = {
  js: C_LIKE, mjs: C_LIKE, cjs: C_LIKE, ts: C_LIKE, tsx: C_LIKE, jsx: C_LIKE,
  java: C_LIKE, c: C_LIKE, h: C_LIKE, cc: C_LIKE, cpp: C_LIKE, hpp: C_LIKE,
  cs: C_LIKE, go: C_LIKE, rs: C_LIKE, swift: C_LIKE, kt: C_LIKE, scala: C_LIKE,
  dart: C_LIKE, scss: C_LIKE, less: C_LIKE,
  css: { block: ['/*', '*/'] },
  py: HASH, rb: HASH, sh: HASH, bash: HASH, zsh: HASH, fish: HASH,
  yml: HASH, yaml: HASH, toml: HASH, tf: HASH, r: HASH, pl: HASH, mk: HASH,
  sql: DASH, hs: DASH, lua: DASH, elm: DASH,
  html: XML, htm: XML, xml: XML, svg: XML, md: XML, markdown: XML,
};
const SPECIAL_BASENAMES = {
  Makefile: HASH, Dockerfile: HASH, '.gitignore': HASH, '.gitattributes': HASH,
};

function syntaxFor(path) {
  const base = basename(path);
  if (SPECIAL_BASENAMES[base]) return SPECIAL_BASENAMES[base];
  const dot = base.lastIndexOf('.');
  if (dot <= 0) return null;
  return COMMENT_SYNTAX[base.slice(dot + 1).toLowerCase()] ?? null;
}

// Head vs base as a pure-insertion diff whose every inserted line is a comment
// (or blank). Greedy subsequence walk: a head line matching the next base line
// is kept content; anything else is an insertion and must be a comment line —
// a line-comment prefix, or inside a block comment the insertion itself opened.
// Trailing code after a block close, a rewritten line, or a removed line all
// fail. Returns null when the change fits, else { kind, line } — kind
// 'rewrote' (base content missing/changed) or 'inserted-code' (a non-comment
// insertion at head line `line`).
function commentOnlyInsertion(baseText, headText, syntax) {
  const baseLines = baseText.split('\n');
  const headLines = headText.split('\n');
  let b = 0;
  let inBlock = false;
  for (let i = 0; i < headLines.length; i++) {
    const line = headLines[i];
    if (!inBlock && b < baseLines.length && line === baseLines[b]) { b++; continue; }
    const t = line.trim();
    if (inBlock) {
      const close = syntax.block[1];
      if (t.includes(close)) {
        if (!t.endsWith(close)) return { kind: 'inserted-code', line: i + 1 };
        inBlock = false;
      }
      continue;
    }
    if (t === '') continue;
    if (syntax.line?.some((p) => t.startsWith(p))) continue;
    if (syntax.block && t.startsWith(syntax.block[0])) {
      const rest = t.slice(syntax.block[0].length);
      if (rest.includes(syntax.block[1])) {
        if (!rest.endsWith(syntax.block[1])) return { kind: 'inserted-code', line: i + 1 };
      } else {
        inBlock = true;
      }
      continue;
    }
    return { kind: 'inserted-code', line: i + 1 };
  }
  if (inBlock || b < baseLines.length) return { kind: 'rewrote' };
  return null;
}

const rule = {
  id: 'growth-write-scope',
  severity: 'blocking',
  scope: 'work',
  doc: 'packs/grow_with_claudinite/skills/growth-extract/SKILL.md',
  description: 'A growth run (a "Claudinite growth:" commit) writes the local packs; elsewhere it only inserts comment lines',
  why: 'extract auto-merges its PR with no human review and dedup runs unattended; outside .claudinite/local/packs/ only a behavior-preserving change — inserting a usage-site comment — is safe to land unreviewed',

  run(work) {
    if (work.onDefaultBranch()) return [];
    if (!work.commits.some((m) => GROWTH_RUN.test(m))) return [];
    const findings = [];
    const outside = (what, file, extra = {}) => findings.push(finding(rule, {
      file,
      what,
      fix: `outside ${LOCAL_ROOTS[0]} a growth run may only insert whole comment lines into existing files (a lesson's usage-site comment); anything more belongs in the local packs, or in an attended, human-reviewed change`,
      ...extra,
    }));

    for (const file of work.deleted.filter((p) => !inSurface(p))) {
      outside(`a "Claudinite growth:" run deleted ${file}, outside ${LOCAL_ROOTS[0]}`, file);
    }
    for (const file of work.changedFiles.filter((p) => !inSurface(p))) {
      const head = work.read(file);
      if (head === null) continue; // gone at head — the deletion pass owns it
      const base = work.readBase(file);
      if (base === null) {
        outside(`a "Claudinite growth:" run created ${file}, outside ${LOCAL_ROOTS[0]}`, file);
        continue;
      }
      const syntax = syntaxFor(file);
      if (!syntax) {
        outside(`a "Claudinite growth:" run edited ${file}, whose comment syntax the gate cannot verify`, file);
        continue;
      }
      const bad = commentOnlyInsertion(base, head, syntax);
      if (bad?.kind === 'rewrote') {
        outside(`a "Claudinite growth:" run rewrote or removed existing lines in ${file}, outside ${LOCAL_ROOTS[0]}`, file);
      } else if (bad) {
        outside(`a "Claudinite growth:" run inserted a non-comment line into ${file}`, file, { line: bad.line });
      }
    }
    return findings.sort((a, b) => a.file.localeCompare(b.file));
  },
};

export default rule;

// CLI body — a CI gate runs this on every PR (self-gating, ~nothing on a
// non-growth branch). In the canon repo the entrypoint is canon-curation's
// growth-scope-gate.mjs (core CI must not name a specific pack — the barriers
// rule); a consumer wiring its own CI would invoke this module directly:
// `node .claudinite/shared/packs/grow_with_claudinite/growth-write-scope.mjs [root]`.
//   exit 0 — not a growth run, or the change fits the growth write surface
//   exit 1 — a growth-titled run reached beyond it
export function runCli(root = process.cwd()) {
  const ctx = buildContext({ root, mode: 'changed' });
  if (!ctx.mergeBase) {
    // Without a merge-base there is no diff — and no branch commits — to read,
    // so there is nothing to self-gate on. Unlike promote-scope (whose CI step
    // already KNOWS it faces a promote PR), refusing here would fail every
    // history-less checkout on ordinary PRs; the Stop-hook run still covers
    // the session side.
    console.log('growth-write-scope: no merge-base with the base branch — nothing to scope.');
    process.exit(0);
  }
  const findings = runRule(rule, ctx);
  if (findings.length) {
    console.error(`growth-write-scope: FAIL — a "Claudinite growth:" run writes ${LOCAL_ROOTS[0]}; elsewhere it may only insert comment lines into existing files. ${findings.length} violation(s):`);
    for (const f of findings) console.error(`  - ${f.what}`);
    console.error('\nKeep the run inside the growth write surface; anything more goes through an attended, human-reviewed change.');
    process.exit(1);
  }
  console.log('growth-write-scope: OK — not a growth run, or the change fits the growth write surface.');
}

if (process.argv[1] && realpathSync(process.argv[1]) === fileURLToPath(import.meta.url)) {
  runCli(process.argv[2] || process.cwd());
}

