+// must be. Deliberately fail-closed: a file type this table doesn't know can't
+// be verified, so it stays out of the unattended surface (the finding says so).
+const C_LIKE = { line: ['//'], block: ['/*', '*/'] };
+const HASH = { line: ['#'] };
+const DASH = { line: ['--'] };
+const XML = { block: ['<!--', '-->'] };
+const COMMENT_SYNTAX = {
+  js: C_LIKE, mjs: C_LIKE, cjs: C_LIKE, ts: C_LIKE, tsx: C_LIKE, jsx: C_LIKE,
+  java: C_LIKE, c: C_LIKE, h: C_LIKE, cc: C_LIKE, cpp: C_LIKE, hpp: C_LIKE,
+  cs: C_LIKE, go: C_LIKE, rs: C_LIKE, swift: C_LIKE, kt: C_LIKE, scala: C_LIKE,
+  dart: C_LIKE, scss: C_LIKE, less: C_LIKE,
+  css: { block: ['/*', '*/'] },
+  py: HASH, rb: HASH, sh: HASH, bash: HASH, zsh: HASH, fish: HASH,
+  yml: HASH, yaml: HASH, toml: HASH, tf: HASH, r: HASH, pl: HASH, mk: HASH,
+  sql: DASH, hs: DASH, lua: DASH, elm: DASH,
+  html: XML, htm: XML, xml: XML, svg: XML, md: XML, markdown: XML,
+};
+const SPECIAL_BASENAMES = {
+  Makefile: HASH, Dockerfile: HASH, '.gitignore': HASH, '.gitattributes': HASH,
+};
+
+function syntaxFor(path) {
