      'tool/run.py': '# gotcha: do_thing() reads cwd — chdir first (#12)\ndo_thing()\n',
      'index.html': '<main>\n<!-- gotcha: keep <main> single — screen readers land here (#12) -->\n</main>\n',
    },
    commitMsg: 'Claudinite growth: extract lessons\n\nRefs #12',
  });
  try {
    assert.deepEqual(runScope(root), []);
  } finally { cleanup(root); }
});

test('growth-write-scope: inserting a non-comment line, a new file, or an unverifiable type is flagged', () => {
  const root = makeRepo({
    base: { 'src/app.mjs': 'call();\n', 'notes.txt': 'keep\n' },
