      'src/app.mjs': 'log("sneaky");\ncall();\n',        // inserted CODE, not a comment
      'src/new-helper.mjs': '// even a pure comment\n',   // a NEW file outside the packs
      'notes.txt': '# looks like a comment\nkeep\n',      // .txt: syntax unknowable
