// Head vs base as a pure-insertion diff whose every inserted line is a comment
// (or blank). Greedy subsequence walk: a head line matching the next base line
// is kept content; anything else is an insertion and must be a comment line —
// a line-comment prefix, or inside a block comment the insertion itself opened.
// Trailing code after a block close, a rewritten line, or a removed line all
// fail. Returns null when the change fits, else { kind, line } — kind
// 'rewrote' (base content missing/changed) or 'inserted-code' (a non-comment
// insertion at head line `line`).
function commentOnlyInsertion(baseText, headText, syntax) {
  const baseLines = baseText.split('\n');
  const headLines = headText.split('\n');
  let b = 0;
  let inBlock = false;
  for (let i = 0; i < headLines.length; i++) {
    const line = headLines[i];
    if (!inBlock && b < baseLines.length && line === baseLines[b]) { b++; continue; }
    const t = line.trim();
    if (inBlock) {
      const close = syntax.block[1];
      if (t.includes(close)) {
        if (!t.endsWith(close)) return { kind: 'inserted-code', line: i + 1 };
        inBlock = false;
      }
      continue;
    }
    if (t === '') continue;
    if (syntax.line?.some((p) => t.startsWith(p))) continue;
    if (syntax.block && t.startsWith(syntax.block[0])) {
      const rest = t.slice(syntax.block[0].length);
      if (rest.includes(syntax.block[1])) {
        if (!rest.endsWith(syntax.block[1])) return { kind: 'inserted-code', line: i + 1 };
      } else {
        inBlock = true;
      }
      continue;
    }
    return { kind: 'inserted-code', line: i + 1 };
  }
  if (inBlock || b < baseLines.length) return { kind: 'rewrote' };
  return null;
}

