52-    out.push({ file: STUB, what: 'the scheduler workflow stub — every member vendors it verbatim' });
53-  }
54-  for (const file of changed) {
55-    // A rule module that BECAME blocking in this change — either newly added, or
56-    // promoted from advisory. That transition is the one that turns a green member
57-    // red without the member changing at all. A rule already blocking at the base
58-    // asked nothing new of anyone, so editing its wording, its `doc` pointer or its
59-    // logic is an ordinary pack edit and stays out of scope: firing on those would
60:    // make every touch of a blocking rule a migration question, which is the
61-    // cried-wolf failure this rule is built to avoid.
